import{_ as t}from"./chunks/cynefin-OW5HDTMX.rPCZ-tep.js";import{o as a,c as s,a as o}from"./chunks/mermaid.C1W4YCqa.js";import"./chunks/mermaid-utils.B0bJactl.js";import"./chunks/mermaid-graph.C5JX3QLV.js";import"./chunks/mermaid-layout.DzVnZVT_.js";const k=JSON.parse('{"title":"Interactive mode","description":"","frontmatter":{},"headers":[],"relativePath":"usage/interactive-mode.md","filePath":"usage/interactive-mode.md"}'),i={name:"usage/interactive-mode.md"};function n(r,e,l,d,c,h){return a(),s("div",null,[...e[0]||(e[0]=[o(`<h1 id="interactive-mode" tabindex="-1">Interactive mode <a class="header-anchor" href="#interactive-mode" aria-label="Permalink to &quot;Interactive mode&quot;">​</a></h1><p>When you run a search without <code>--no-interactive</code> (and outside a CI environment), <code>github-code-search</code> launches a full-screen TUI. This is the main advantage of the tool over GitHub&#39;s web search: results are grouped by repository, and you can fold, navigate, filter, and select exactly what you need.</p><h2 id="launching-the-tui" tabindex="-1">Launching the TUI <a class="header-anchor" href="#launching-the-tui" aria-label="Permalink to &quot;Launching the TUI&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light-high-contrast github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#702C00;--shiki-dark:#B392F0;">github-code-search</span><span style="--shiki-light:#032563;--shiki-dark:#9ECBFF;"> &quot;useFeatureFlag&quot;</span><span style="--shiki-light:#023B95;--shiki-dark:#79B8FF;"> --org</span><span style="--shiki-light:#032563;--shiki-dark:#9ECBFF;"> fulll</span></span></code></pre></div><h2 id="tui-overview" tabindex="-1">TUI overview <a class="header-anchor" href="#tui-overview" aria-label="Permalink to &quot;TUI overview&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light-high-contrast github-dark vp-code" tabindex="0"><code><span class="line"><span> github-code-search  useFeatureFlag in fulll</span></span>
<span class="line"><span>3 repos · 4 files</span></span>
<span class="line"><span>← / → fold/unfold  ↑ / ↓ navigate  spc select  a all  n none  f filter  h help  ↵ confirm  q quit</span></span>
<span class="line"><span></span></span>
<span class="line"><span>▸   fulll/service-b                                         3 matches</span></span>
<span class="line"><span>▾ ✓ fulll/service-a                                       2 matches</span></span>
<span class="line"><span>      ✓ src/middlewares/featureFlags.ts</span></span>
<span class="line"><span>            …const flag = useFeatureFlag(&#39;new-onboarding&#39;); if (!flag) return next();…</span></span>
<span class="line"><span>      ✓ tests/unit/featureFlags.test.ts</span></span>
<span class="line"><span>            …expect(useFeatureFlag(&#39;new-onboarding&#39;)).toBe(true);…</span></span>
<span class="line"><span>▸   fulll/legacy-app                                     1 match</span></span></code></pre></div><ul><li><code>▸</code> — folded repo (extracts hidden)</li><li><code>▾</code> — unfolded repo (extracts visible)</li><li><code>✓</code> — selected (green in the terminal)</li><li><code></code> — deselected (space — keeps columns aligned)</li><li>Match counts are right-aligned to the terminal width</li><li>The header badge <code>github-code-search</code> is displayed on a violet background</li></ul><h2 id="keyboard-shortcuts" tabindex="-1">Keyboard shortcuts <a class="header-anchor" href="#keyboard-shortcuts" aria-label="Permalink to &quot;Keyboard shortcuts&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Key</th><th>Action</th></tr></thead><tbody><tr><td><code>↑</code> / <code>↓</code></td><td>Navigate between repos and extracts</td></tr><tr><td><code>←</code></td><td>Fold the repo under the cursor</td></tr><tr><td><code>→</code></td><td>Unfold the repo under the cursor</td></tr><tr><td><code>Space</code></td><td>Select / deselect the current repo or extract</td></tr><tr><td><code>a</code></td><td>Select <strong>all</strong> — on a repo row: all repos and extracts; on an extract row: all extracts in that repo. Respects any active filter.</td></tr><tr><td><code>n</code></td><td>Select <strong>none</strong> — same context rules as <code>a</code>. Respects any active filter.</td></tr><tr><td><code>f</code></td><td>Open the <strong>filter bar</strong> — type to narrow visible repos or files</td></tr><tr><td><code>t</code></td><td>Cycle the <strong>filter target</strong>: <code>path</code> → <code>content</code> → <code>repo</code> → <code>path</code>. When on a <strong>picked repo</strong> (marked <code>◈</code>, <code>--group-by-team-prefix</code> active): enter re-pick mode instead.</td></tr><tr><td><code>r</code></td><td><strong>Reset</strong> the active filter and show all repos / extracts</td></tr><tr><td><code>h</code> / <code>?</code></td><td>Toggle the <strong>help overlay</strong></td></tr><tr><td><code>Enter</code></td><td>Confirm and print selected results (also closes the help overlay)</td></tr><tr><td><code>q</code> / <code>Ctrl+C</code></td><td>Quit without printing</td></tr></tbody></table><h2 id="mouse-support" tabindex="-1">Mouse support <a class="header-anchor" href="#mouse-support" aria-label="Permalink to &quot;Mouse support&quot;">​</a></h2><p>The TUI supports mouse interaction via the terminal&#39;s SGR mouse protocol. You can navigate, select, and fold repos using your mouse alongside keyboard shortcuts.</p><h3 id="scrolling" tabindex="-1">Scrolling <a class="header-anchor" href="#scrolling" aria-label="Permalink to &quot;Scrolling&quot;">​</a></h3><ul><li><strong>Scroll wheel</strong> (up/down) — move the viewport up or down by 3 rows.</li><li><strong>Momentum scrolling</strong> (trackpad): clicks are ignored during and immediately after the scroll gesture to prevent accidental selections while the scroll is still decelerating.</li></ul><h3 id="single-click" tabindex="-1">Single-click <a class="header-anchor" href="#single-click" aria-label="Permalink to &quot;Single-click&quot;">​</a></h3><ul><li><strong>Single-click on any row</strong> — move the cursor to that row (equivalent to <code>↑</code>/<code>↓</code> navigation).</li></ul><h3 id="double-click" tabindex="-1">Double-click <a class="header-anchor" href="#double-click" aria-label="Permalink to &quot;Double-click&quot;">​</a></h3><p>Double-click actions depend on both the <strong>row type</strong> (repo or extract) and the <strong>click zone</strong> (columns 1–3 vs. columns 4+):</p><p><strong>On a repo row</strong> (<code>▸ ✓ repo-name</code>):</p><table tabindex="0"><thead><tr><th>Click zone</th><th>Action</th></tr></thead><tbody><tr><td>Fold control (columns 1–2)</td><td>Toggle fold (<code>←</code> / <code>→</code>)</td></tr><tr><td>Checkbox or content (columns 4+)</td><td>Toggle repo selection (<code>Space</code>)</td></tr></tbody></table><p><strong>On an extract row</strong> (<code> ✓ path:line:col</code>):</p><table tabindex="0"><thead><tr><th>Click zone</th><th>Action</th></tr></thead><tbody><tr><td>Content area (columns 4+)</td><td>Toggle extract selection</td></tr><tr><td>Navigation-only zone (columns 1–3)</td><td>No action (single-click only)</td></tr></tbody></table><p>The checkbox zone (column 4 and beyond) is <strong>full-width for selection</strong>, so you can double-click anywhere on the row content to toggle selection.</p><h3 id="accessibility-note" tabindex="-1">Accessibility note <a class="header-anchor" href="#accessibility-note" aria-label="Permalink to &quot;Accessibility note&quot;">​</a></h3><p>Mouse support is optional; all features are fully accessible via keyboard. Many users prefer the keyboard-only workflow for speed and precision during large searches.</p><h2 id="selection-behaviour" tabindex="-1">Selection behaviour <a class="header-anchor" href="#selection-behaviour" aria-label="Permalink to &quot;Selection behaviour&quot;">​</a></h2><ul><li><strong>Selecting a repo row</strong> (<code>Space</code>) cascades to all its extracts.</li><li><strong>Deselecting a repo row</strong> deselects all its extracts.</li><li><strong>Selecting an individual extract</strong> keeps the parent repo selected as long as at least one extract is selected.</li><li><strong>Deselecting the last extract</strong> in a repo automatically deselects the repo too.</li></ul><h2 id="filter-mode" tabindex="-1">Filter mode <a class="header-anchor" href="#filter-mode" aria-label="Permalink to &quot;Filter mode&quot;">​</a></h2><p>Press <code>f</code> to enter filter mode. A two-line bar appears at the top of the results:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light-high-contrast github-dark vp-code" tabindex="0"><code><span class="line"><span>🔍 [path]  src/▌                            3 repos · 5 files</span></span>
<span class="line"><span>          ←→ move  ·  ⌥←→ word  ·  ⌥⌫ del word  ·  Tab regex  ·  Shift+Tab target  ·  ↵ OK  ·  Esc cancel</span></span></code></pre></div><ul><li><strong>Line 1</strong>: the filter input field with a text cursor (<code>▌</code>), plus live stats on the right (how many repos and files are currently visible).</li><li><strong>Line 2</strong>: available shortcuts, indented to align with the input text.</li></ul><h3 id="filter-targets" tabindex="-1">Filter targets <a class="header-anchor" href="#filter-targets" aria-label="Permalink to &quot;Filter targets&quot;">​</a></h3><p>Press <code>t</code> (outside filter mode) or <code>Shift+Tab</code> (inside filter mode) to cycle through three matching modes:</p><table tabindex="0"><thead><tr><th>Badge</th><th>Target</th><th>What is matched</th><th>Unit shown/hidden</th></tr></thead><tbody><tr><td><code>[path]</code></td><td><code>path</code></td><td>File path — default, case-insensitive substring</td><td>Individual file</td></tr><tr><td><code>[content]</code></td><td><code>content</code></td><td>Code fragment text returned by GitHub Search</td><td>Individual file</td></tr><tr><td><code>[repo]</code></td><td><code>repo</code></td><td>Full repository name (<code>org/repo</code>), case-insensitive</td><td>Entire repo</td></tr></tbody></table><p>The matching part is highlighted in <strong>yellow</strong> in the result list so you can instantly see why a row is visible.</p><h3 id="regex-mode" tabindex="-1">Regex mode <a class="header-anchor" href="#regex-mode" aria-label="Permalink to &quot;Regex mode&quot;">​</a></h3><p>Press <code>Tab</code> in filter mode to toggle regular-expression matching. The badge updates to <code>[path·regex]</code> (or <code>[content·regex]</code>, etc.) while regex is active. If the expression is invalid, it matches nothing (no results are shown until you correct the pattern).</p><h3 id="confirmed-filter" tabindex="-1">Confirmed filter <a class="header-anchor" href="#confirmed-filter" aria-label="Permalink to &quot;Confirmed filter&quot;">​</a></h3><p>After pressing <code>Enter</code> the filter is locked and the bar shows a compact summary:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light-high-contrast github-dark vp-code" tabindex="0"><code><span class="line"><span>🔍 [repo]  billing  3 matches in 1 repo shown · 2 hidden in 2 repos  r to reset</span></span></code></pre></div><p>Press <code>r</code> at any time to clear the filter and show all results again.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p><code>a</code> (select all) and <code>n</code> (select none) always operate only on the <strong>currently visible</strong> repos and extracts when a filter is active. The filter target is taken into account: with <code>filterTarget=repo</code> only repos whose name matches are affected.</p></div><h2 id="full-workflow-example" tabindex="-1">Full workflow example <a class="header-anchor" href="#full-workflow-example" aria-label="Permalink to &quot;Full workflow example&quot;">​</a></h2><p><strong>1 — Run the search:</strong></p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light-high-contrast github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#702C00;--shiki-dark:#B392F0;">github-code-search</span><span style="--shiki-light:#032563;--shiki-dark:#9ECBFF;"> &quot;useFeatureFlag&quot;</span><span style="--shiki-light:#023B95;--shiki-dark:#79B8FF;"> --org</span><span style="--shiki-light:#032563;--shiki-dark:#9ECBFF;"> fulll</span></span></code></pre></div><p><strong>2 — Navigate with <code>↑</code>/<code>↓</code>, unfold repos with <code>→</code>.</strong></p><p><strong>3 — Filter to <code>src/</code> files only:</strong></p><p>Press <code>f</code>, type <code>src/</code>, press <code>Enter</code>.</p><p><strong>4 — Select all visible extracts:</strong></p><p>Press <code>a</code> on a repo row to select all its visible extracts.</p><p><strong>5 — Deselect a specific extract:</strong></p><p>Navigate to it with <code>↑</code>/<code>↓</code>, press <code>Space</code>.</p><p><strong>6 — Confirm:</strong></p><p>Press <code>Enter</code>. The selected results are printed to stdout, along with a replay command.</p><h2 id="output-and-replay-command" tabindex="-1">Output and replay command <a class="header-anchor" href="#output-and-replay-command" aria-label="Permalink to &quot;Output and replay command&quot;">​</a></h2><p>After pressing <code>Enter</code>:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light-high-contrast github-dark vp-code" tabindex="0"><code><span class="line"><span>2 repos · 2 files selected</span></span>
<span class="line"><span></span></span>
<span class="line"><span>- **fulll/service-a** (1 match)</span></span>
<span class="line"><span>  - [ ] [src/middlewares/featureFlags.ts:2:19](https://github.com/fulll/service-a/blob/main/src/middlewares/featureFlags.ts#L2)</span></span>
<span class="line"><span>- **fulll/service-b** (1 match)</span></span>
<span class="line"><span>  - [ ] [src/flags.ts:3:14](https://github.com/fulll/service-b/blob/main/src/flags.ts#L3)</span></span></code></pre></div><details><summary>replay command</summary><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light-high-contrast github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#702C00;--shiki-dark:#B392F0;">github-code-search</span><span style="--shiki-light:#032563;--shiki-dark:#9ECBFF;"> &quot;useFeatureFlag&quot;</span><span style="--shiki-light:#023B95;--shiki-dark:#79B8FF;"> --org</span><span style="--shiki-light:#032563;--shiki-dark:#9ECBFF;"> fulll</span><span style="--shiki-light:#023B95;--shiki-dark:#79B8FF;"> --no-interactive</span><span style="--shiki-light:#A0111F;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#023B95;--shiki-dark:#79B8FF;">  --exclude-repositories</span><span style="--shiki-light:#032563;--shiki-dark:#9ECBFF;"> legacy-app</span></span></code></pre></div></details><p>The replay command encodes your exact selection (exclusions) so you can reproduce the result in CI without the UI. See <a href="/github-code-search/v2/usage/non-interactive-mode.html">Non-interactive mode</a> for more.</p><h2 id="output-format" tabindex="-1">Output format <a class="header-anchor" href="#output-format" aria-label="Permalink to &quot;Output format&quot;">​</a></h2><p>By default output is Markdown. Pass <code>--format json</code> to get a JSON payload instead:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light-high-contrast github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#702C00;--shiki-dark:#B392F0;">github-code-search</span><span style="--shiki-light:#032563;--shiki-dark:#9ECBFF;"> &quot;useFeatureFlag&quot;</span><span style="--shiki-light:#023B95;--shiki-dark:#79B8FF;"> --org</span><span style="--shiki-light:#032563;--shiki-dark:#9ECBFF;"> fulll</span><span style="--shiki-light:#023B95;--shiki-dark:#79B8FF;"> --format</span><span style="--shiki-light:#032563;--shiki-dark:#9ECBFF;"> json</span></span></code></pre></div><p>See <a href="/github-code-search/v2/usage/output-formats.html">Output formats</a> for the full reference.</p>`,62)])])}const f=t(i,[["render",n]]);export{k as __pageData,f as default};
